{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C27"],
      "claim": "Hydrocortisone absolute oral bioavailability was 0.95 in healthy adults, supporting F >= 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C61"],
      "claim": "Amoxicillin absolute oral bioavailability was 0.873 in a patient pharmacokinetic model, supporting F >= 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C91"],
      "claim": "Naltrexone absolute oral bioavailability was 5% in healthy and post-addict volunteers, arguing against F >= 20%.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Nine of ten transferred evidence molecules support high oral bioavailability, with absolute F values mostly 29-96%; the only clearly negative molecule (naltrexone, F ~5%) has the lowest assay-transfer score. Overall, F >= 20% is better supported.",
  "evidence_gaps": [
    "Molecule 5 shows wide individual absolute F values (9-39%), with some below 20%, creating threshold uncertainty.",
    "Molecule 1 has conflicting absolute F estimates (0.344 vs 0.95) and a poor-bioavailability suspension record that may reflect formulation issues.",
    "One record under Molecule 3 refers to 'finasartan' rather than finasteride and was discounted as a provenance conflict."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

